import { GoogleGenAI } from "@google/genai";
import { PERSONAL_INFO, SERVICES, SKILLS } from "./constants";

const apiKey = process.env.API_KEY || "";
const ai = new GoogleGenAI({ apiKey });

const systemPrompt = `
You are the AI Creative Assistant for ${PERSONAL_INFO.name}, also known as ${PERSONAL_INFO.brand}.
Your goal is to answer questions from potential clients about ${PERSONAL_INFO.name}'s work.

Background Info:
- Role: Motion Graphics Designer & Video Editor.
- Services: ${SERVICES.map(s => s.title).join(", ")}.
- Skills: ${SKILLS.map(s => s.name).join(", ")}.
- Contact: Email is ${PERSONAL_INFO.email}, WhatsApp is ${PERSONAL_INFO.phone}.
- Personality: Professional, creative, helpful, and enthusiastic about motion design.

Answer concisely and encourage the user to reach out via WhatsApp or Email if they have a specific project in mind.
If they ask about pricing, mention that it varies by project complexity and they should get a custom quote.
`;

export const getAIResponse = async (userMessage: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userMessage,
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.7,
      },
    });
    return response.text || "I'm having a little trouble thinking right now. Could you try asking again?";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "I'm sorry, I'm currently offline. Please reach out to Mosto directly via the contact form!";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { getAIResponse } from '../geminiService';

const AIChatAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'ai'; text: string }[]>([
    { role: 'ai', text: "Hi! I'm Mosto's AI assistant. Ask me anything about his services or background!" }
  ]);
  const [input, setInput] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg = input;
    setInput("");
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    const aiMsg = await getAIResponse(userMsg);
    setIsTyping(false);
    setMessages(prev => [...prev, { role: 'ai', text: aiMsg }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-50">
      {isOpen ? (
        <div className="w-80 md:w-96 glass rounded-2xl flex flex-col overflow-hidden shadow-2xl border border-purple-500/30 animate-in fade-in zoom-in duration-300">
          <div className="bg-gradient-to-r from-purple-600 to-cyan-500 p-4 flex justify-between items-center">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center">
                <i className="fas fa-robot text-white"></i>
              </div>
              <span className="font-bold text-white">Creative Assistant</span>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-white hover:text-gray-200">
              <i className="fas fa-times"></i>
            </button>
          </div>

          <div className="h-96 overflow-y-auto p-4 space-y-4">
            {messages.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${
                  msg.role === 'user' 
                    ? 'bg-purple-600 text-white rounded-br-none' 
                    : 'bg-white/10 text-gray-200 rounded-bl-none'
                }`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white/10 text-gray-400 p-3 rounded-2xl text-xs rounded-bl-none italic">
                  Mosto's AI is thinking...
                </div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          <div className="p-4 bg-white/5 flex gap-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Ask about projects, pricing..."
              className="flex-1 bg-white/10 border border-white/20 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-cyan-400"
            />
            <button 
              onClick={handleSend}
              className="bg-cyan-500 hover:bg-cyan-600 text-white w-10 h-10 rounded-lg flex items-center justify-center transition-colors"
            >
              <i className="fas fa-paper-plane"></i>
            </button>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setIsOpen(true)}
          className="w-16 h-16 bg-gradient-to-tr from-purple-600 to-cyan-500 rounded-full flex items-center justify-center shadow-lg hover:scale-110 transition-transform group"
        >
          <i className="fas fa-comment-dots text-white text-2xl group-hover:animate-bounce"></i>
          <span className="absolute -top-1 -right-1 flex h-4 w-4">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-cyan-400 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-4 w-4 bg-cyan-500"></span>
          </span>
        </button>
      )}
    </div>
  );
};

export default AIChatAssistant;

